import json
import shlex
import re

from moler.exceptions import ParsingDone, WrongUsage

from ta_moler.cmd.positioner_ec.generic_positioner_ec import GenericPositionerEC

__author__ = "Marcin Usielski"
__copyright__ = "Copyright (C) 2023, Nokia"
__email__ = "marcin.usielski@nokia.com"


class SendRequest(GenericPositionerEC):
    """send_request.py command."""

    def __init__(
        self,
        connection,
        address=None,
        method="get",
        payload=None,
        prompt=None,
        newline_chars=None,
        runner=None,
        server=None,
        port=None,
        positioner=None,
        operation=None,
    ):
        """
        Create send_request command.

        :param connection: moler connection to device, terminal when command is executed.
        :param address: full address to send request
        :param method: method of communication with server, get or put or post
        :param payload: string or dict with payload
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        :param server: ip of server, use if address is None
        :param port: port on server, use if address is None
        :param positioner: name of positioner, use if address is None
        :param operation: name of operation, use if address is None

        """
        super(SendRequest, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.payload = payload
        self.address = address
        self.method = method
        self.server = server
        self.port = port
        self.positioner = positioner
        self.operation = operation
        self.ret_required = True
        self.timeout = 30

        if address is None and (server is None or positioner is None or operation is None):
            msg = f"Should provide address '{address}' or (server '{server}' and positioner '{positioner}' and operation '{operation}')."
            raise WrongUsage(msg)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        if self.address is None:
            self.address = f"http://{self.server}"
            if self.port is not None:
                self.address = f"{self.address}:{self.port}"
            self.address = f"{self.address}/api/{self.positioner}/{self.operation}"
        cmd = f"python3 send_request.py -hm {self.method} -a {shlex.quote(self.address)}"
        cmd = f"{cmd} -t {round(self.timeout - 0.5, 1)}"
        if self.payload is not None:
            if isinstance(self.payload, dict):
                self.payload = json.dumps(self.payload, sort_keys=True)
            escaped_payload = shlex.quote(self.payload)
            cmd = f"{cmd} -p {escaped_payload}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse output.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_code(line=line)
                self._parse_json(line=line)
                self._parse_communication_time(line=line)
            except ParsingDone:
                pass
        super(SendRequest, self).on_new_line(line=line, is_full_line=is_full_line)

    # Communication time: 0.005 seconds
    _re_communication_time = re.compile(r"Communication time: '(?P<TIME>[\d.]+)' seconds")

    def _parse_communication_time(self, line):
        if self._regex_helper.search_compiled(SendRequest._re_communication_time, line):
            self.current_ret["communication_time"] = float(self._regex_helper.group("TIME"))
            raise ParsingDone()

    # code: '200'
    _re_code = re.compile(r"\s*<?code:\s+'(?P<CODE>\d+)'")

    def _parse_code(self, line):
        if self._regex_helper.search_compiled(SendRequest._re_code, line):
            self.current_ret["code"] = int(self._regex_helper.group("CODE"))
            raise ParsingDone()

    # json: '{"height":{"isPowered":false,"isHomed":true,"acceleration":0,"deceleration":0,"speed":0,"lowLimit":null,"highLimit":null},"azimuth":{"isPowered":false,"isHomed":true,"acceleration":0,"deceleration":0,"speed":0,"lowLimit":null,"highLimit":null},"elevation":{"isPowered":false,"isHomed":true,"acceleration":0,"deceleration":0,"speed":0,"lowLimit":null,"highLimit":null},"z":{"isPowered":false,"isHomed":true,"acceleration":0,"deceleration":0,"speed":0,"lowLimit":null,"highLimit":null},"x":{"isPowered":false,"isHomed":true,"acceleration":0,"deceleration":0,"speed":0,"lowLimit":null,"highLimit":null},"rotation":{"isPowered":false,"isHomed":true,"acceleration":0,"deceleration":0,"speed":0,"lowLimit":null,"highLimit":null}}'
    _re_json = re.compile(r"^\s*<?json:\s+'(?P<JSON>.+)'")

    def _parse_json(self, line):
        if "code" in self.current_ret and 200 == self.current_ret["code"] and self._regex_helper.search_compiled(SendRequest._re_json, line):
            json_txt = self._regex_helper.group("JSON")
            self.current_ret["json_txt"] = json_txt
            self.current_ret["json"] = json.loads(json_txt)
            raise ParsingDone()


